jsonTools.init:
function init(eli) {
  if (!eli || !eli.host || typeof eli.host.runRaw !== "function") return;
  var SPEC = { font: "Arial", size: 10, lineSpacing: 12, spaceBefore: 0, spaceAfter: 0 };

  function _toast(msg, kind) { if (typeof showToast === "function") showToast(msg, kind); }

  // Formatting only: words, bold, italics and colours stay. Tracking is paused so it lands clean, then restored.
  function _apply() {
    return eli.host.runRaw("email_formatter:apply", function (ctx) {
      var doc = ctx.document, sel = doc.getSelection(), bodyParas = doc.body.paragraphs, selParas = sel.paragraphs;
      doc.load("changeTrackingMode");
      sel.load("text");
      bodyParas.load("items");
      selParas.load("items");
      return ctx.sync().then(function () {
        var whole = !String(sel.text || "").trim();
        var target = whole ? doc.body : sel, paras = whole ? bodyParas : selParas;
        var prev = doc.changeTrackingMode, pause = prev && prev !== "Off";
        if (pause) doc.changeTrackingMode = "Off";
        target.font.name = SPEC.font;
        target.font.size = SPEC.size;
        paras.items.forEach(function (p) {
          p.lineSpacing = SPEC.lineSpacing;
          p.spaceBefore = SPEC.spaceBefore;
          p.spaceAfter = SPEC.spaceAfter;
        });
        if (pause) doc.changeTrackingMode = prev;
        return ctx.sync().then(function () { return { ok: true, whole: whole, paragraphs: paras.items.length }; });
      });
    }).then(function (res) {
      _toast("Email format applied to " + (res.whole ? "the whole document" : "the selection") + " · Arial 10pt, single spacing", "ok");
      return res;
    }, function (e) {
      eli.log.event("tool", "email_formatter_failed", { msg: e && e.message });
      _toast("Email Formatter couldn't change the text: " + ((e && e.message) || "unknown error"), "err");
      return { ok: false };
    });
  }

  function _fromTile() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedEmailFormatter"); } catch (e) {}
    return _apply();
  }
  eli.register({ tile: { app_email_formatter: _fromTile }, email_formatter: { apply: _apply } });
}
